xwikidoc.content:
{{groovy}}
def escapetool = new org.xwiki.velocity.tools.EscapeTool()
def configPage = "Office365.Office365Config"
def activateSearch = xwiki.getDocument(configPage).getValue("activateSearchExtension")
if (activateSearch==null)
 activateSearch = xwiki.getDocument("xwiki:${configPage}").getValue("activateSearchExtension")
if (activateSearch==1) {
if (request.text) {
 def azureAuth = xwiki.parseGroovyFromPage("Office365.Groovy")
 azureAuth.setXWiki(xwiki, xcontext, doc)

 if (!azureAuth.authenticate()) {
 } else {
 def searchResults = azureAuth.searchSitesForText(request.text);
 def foundDocumentCount = 0;
 def errorFlag = false;
 for (res in searchResults.values()) {
   if (res != null && res.value != null) {
     foundDocumentCount += res.value.size();
   } else {
     errorFlag = true;
   }
 }
 def otitle = services.localization.render('office365.uiextension.nomatchingdocs', [ request.text ]);
 if (foundDocumentCount>0)
  otitle = services.localization.render('office365.uiextension.matchingdocs', [ foundDocumentCount, request.text ]);
 println """(% class="search-widget search-facets col-xs-12 col-sm-12" style="padding: 5px; margin-bottom: 10px;" %)
(((
{{showhide showmessage="${services.rendering.escape(otitle, doc.getSyntax())}"
  hidemessage="${services.rendering.escape(otitle, doc.getSyntax())}" }}"""

 if (errorFlag) {
  println services.rendering.escape(services.localization.render('office365.uiextension.error', [ request.text ]), doc.getSyntax());
 }
 for (site in searchResults.keySet()) {
  def res = searchResults.get(site);
  if (res != null && res.value != null) {
    for (item in res.value) {
      println """* ${services.rendering.escape(site, doc.getSyntax())} / [[${services.rendering.escape(services.rendering.escape(item.name, doc.getSyntax()), doc.getSyntax())}>>${services.rendering.escape(item.webUrl, doc.getSyntax())}||target="_blank"]]"""
    }
  }
 }
 println "{{/showhide}}"
 println ")))"
 }
 if (request.debug && hasAdmin)
   println "DEBUG: {{{ ${azureAuth.debugStr} }}}"
}
}
{{/groovy}}
